import fs from "node:fs"; import path from "node:path"; import http from "node:http"
import { chromium } from "playwright-core"
const OUT = path.join(process.cwd(), ".build")
const MIME = { ".png": "image/png", ".html": "text/html", ".js": "text/javascript", ".css": "text/css", ".json": "application/json" }
const server = http.createServer((req, res) => {
  const p = path.join(OUT, decodeURIComponent(new URL(req.url, "http://x").pathname))
  if (!fs.existsSync(p) || fs.statSync(p).isDirectory()) return res.writeHead(404).end()
  res.writeHead(200, { "content-type": MIME[path.extname(p)] ?? "application/octet-stream" }); fs.createReadStream(p).pipe(res)
})
await new Promise((r) => server.listen(0, "127.0.0.1", r))
const url = `http://127.0.0.1:${server.address().port}/index.html`
const browser = await chromium.launch({ executablePath: process.env.CHROMIUM_PATH ?? "/opt/pw-browsers/chromium" })
const page = await browser.newPage({ viewport: { width: 1440, height: 900 } })
await page.goto(url); await page.waitForFunction(() => window.__READY__ === true)
const info = await page.evaluate(() => {
  const r = (el) => { const b = el.getBoundingClientRect(); return `${Math.round(b.x)},${Math.round(b.y + window.scrollY)} ${Math.round(b.width)}x${Math.round(b.height)}` }
  const strips = [...document.querySelectorAll("[data-slot=figure-strip]")]
  return strips.map((s) => ({
    strip: r(s),
    inner: [...s.querySelectorAll("*")].filter((e) => ["scroll-area-scrollbar","scroll-area-viewport","scroll-area-thumb","scroll-area-corner"].includes(e.getAttribute("data-slot")) || e.getAttribute("data-orientation")).map((e) => `${e.tagName}:${e.getAttribute("data-slot")}/${e.getAttribute("data-orientation")} ${r(e)} op=${getComputedStyle(e).opacity} bg=${getComputedStyle(e).backgroundColor}`),
  }))
})
console.log(JSON.stringify(info, null, 1))
await browser.close(); server.close()
EOF
